WITH seed (skill_name, difficulty, text, question_type, options) AS (
  VALUES
    ('TypeScript', 'EASY', 'What does a TypeScript interface describe?', 'SINGLE_CHOICE', '[{"text":"The shape of an object","is_correct":true},{"text":"A running JavaScript process","is_correct":false},{"text":"A database table","is_correct":false},{"text":"A CSS selector","is_correct":false}]'::jsonb),
    ('TypeScript', 'EASY', 'Which type is safer than any when a value is not yet known?', 'SINGLE_CHOICE', '[{"text":"unknown","is_correct":true},{"text":"void","is_correct":false},{"text":"never","is_correct":false},{"text":"object","is_correct":false}]'::jsonb),
    ('TypeScript', 'EASY', 'What does an optional property marker mean?', 'SINGLE_CHOICE', '[{"text":"The property may be absent","is_correct":true},{"text":"The property is always null","is_correct":false},{"text":"The property is read only","is_correct":false},{"text":"The property is private","is_correct":false}]'::jsonb),
    ('TypeScript', 'MEDIUM', 'What is a union type?', 'SINGLE_CHOICE', '[{"text":"A value that can match one of several listed types","is_correct":true},{"text":"A type that joins two running processes","is_correct":false},{"text":"A class with multiple constructors","is_correct":false},{"text":"A type that exists only at runtime","is_correct":false}]'::jsonb),
    ('TypeScript', 'MEDIUM', 'What is a generic used for?', 'SINGLE_CHOICE', '[{"text":"Writing reusable code that preserves type information","is_correct":true},{"text":"Generating random values","is_correct":false},{"text":"Converting TypeScript to CSS","is_correct":false},{"text":"Preventing functions from returning values","is_correct":false}]'::jsonb),
    ('TypeScript', 'MEDIUM', 'What does keyof T produce?', 'SINGLE_CHOICE', '[{"text":"A union of the keys of T","is_correct":true},{"text":"The values stored in T","is_correct":false},{"text":"A copy of T at runtime","is_correct":false},{"text":"The number of properties in T","is_correct":false}]'::jsonb),
    ('TypeScript', 'MEDIUM', 'Which statements about type narrowing are correct?', 'MULTIPLE_CHOICE', '[{"text":"A typeof check can narrow a union","is_correct":true},{"text":"An instanceof check can narrow class instances","is_correct":true},{"text":"Narrowing always changes the runtime value","is_correct":false},{"text":"A type assertion validates input at runtime","is_correct":false}]'::jsonb),
    ('TypeScript', 'HARD', 'What does never represent?', 'SINGLE_CHOICE', '[{"text":"A value that cannot occur","is_correct":true},{"text":"Any possible value","is_correct":false},{"text":"An omitted optional property","is_correct":false},{"text":"A promise that is still pending","is_correct":false}]'::jsonb),
    ('TypeScript', 'HARD', 'What does the infer keyword do in a conditional type?', 'SINGLE_CHOICE', '[{"text":"Captures a type for later use in the conditional type","is_correct":true},{"text":"Loads a module at runtime","is_correct":false},{"text":"Infers values from a database","is_correct":false},{"text":"Disables type checking in a file","is_correct":false}]'::jsonb),
    ('TypeScript', 'HARD', 'Which statements about readonly are correct?', 'MULTIPLE_CHOICE', '[{"text":"It prevents assignment through the typed reference","is_correct":true},{"text":"It does not deeply freeze nested runtime objects","is_correct":true},{"text":"It encrypts the property in memory","is_correct":false},{"text":"It makes a property optional","is_correct":false}]'::jsonb),

    ('React', 'EASY', 'What does a React component return?', 'SINGLE_CHOICE', '[{"text":"A description of UI, usually JSX","is_correct":true},{"text":"A database connection","is_correct":false},{"text":"A CSS file only","is_correct":false},{"text":"A browser window","is_correct":false}]'::jsonb),
    ('React', 'EASY', 'What is a prop?', 'SINGLE_CHOICE', '[{"text":"Input passed from a parent component","is_correct":true},{"text":"A global browser event","is_correct":false},{"text":"A CSS animation","is_correct":false},{"text":"A database index","is_correct":false}]'::jsonb),
    ('React', 'EASY', 'What does useState provide?', 'SINGLE_CHOICE', '[{"text":"A state value and a state update function","is_correct":true},{"text":"A route and a URL","is_correct":false},{"text":"A server and a socket","is_correct":false},{"text":"A DOM node and its CSS","is_correct":false}]'::jsonb),
    ('React', 'MEDIUM', 'Why should list items have stable keys?', 'SINGLE_CHOICE', '[{"text":"They help React match items between renders","is_correct":true},{"text":"They encrypt list values","is_correct":false},{"text":"They prevent all rerenders","is_correct":false},{"text":"They set the visual order in CSS","is_correct":false}]'::jsonb),
    ('React', 'MEDIUM', 'When does an effect with an empty dependency array run?', 'SINGLE_CHOICE', '[{"text":"After the component is mounted","is_correct":true},{"text":"Before every render","is_correct":false},{"text":"Only when the browser closes","is_correct":false},{"text":"Only after a state update","is_correct":false}]'::jsonb),
    ('React', 'MEDIUM', 'Which statements about controlled inputs are correct?', 'MULTIPLE_CHOICE', '[{"text":"Their displayed value is driven by React state","is_correct":true},{"text":"They update state from change events","is_correct":true},{"text":"They cannot be edited by the user","is_correct":false},{"text":"They require direct DOM mutation on every keystroke","is_correct":false}]'::jsonb),
    ('React', 'MEDIUM', 'What problem does context help solve?', 'SINGLE_CHOICE', '[{"text":"Passing shared values through many component levels","is_correct":true},{"text":"Compiling JSX in the browser","is_correct":false},{"text":"Creating SQL tables","is_correct":false},{"text":"Replacing every local state variable","is_correct":false}]'::jsonb),
    ('React', 'HARD', 'What does useMemo cache?', 'SINGLE_CHOICE', '[{"text":"A computed value between renders while dependencies stay equal","is_correct":true},{"text":"A component tree in local storage","is_correct":false},{"text":"A network request forever","is_correct":false},{"text":"A state update until page reload","is_correct":false}]'::jsonb),
    ('React', 'HARD', 'Why must hooks be called in the same order on every render?', 'SINGLE_CHOICE', '[{"text":"React associates hook state with call order","is_correct":true},{"text":"JavaScript requires it for async functions","is_correct":false},{"text":"The browser sorts hooks alphabetically","is_correct":false},{"text":"It is needed to preserve CSS specificity","is_correct":false}]'::jsonb),
    ('React', 'HARD', 'Which statements about effect cleanup are correct?', 'MULTIPLE_CHOICE', '[{"text":"Cleanup runs before an effect reruns with changed dependencies","is_correct":true},{"text":"Cleanup runs when the component unmounts","is_correct":true},{"text":"Cleanup automatically cancels every promise","is_correct":false},{"text":"Cleanup runs before the first effect setup","is_correct":false}]'::jsonb),

    ('Node.js', 'EASY', 'What is Node.js?', 'SINGLE_CHOICE', '[{"text":"A JavaScript runtime outside the browser","is_correct":true},{"text":"A JavaScript framework for styling","is_correct":false},{"text":"A relational database","is_correct":false},{"text":"A browser extension API","is_correct":false}]'::jsonb),
    ('Node.js', 'EASY', 'Which global object provides process information?', 'SINGLE_CHOICE', '[{"text":"process","is_correct":true},{"text":"document","is_correct":false},{"text":"window","is_correct":false},{"text":"navigator","is_correct":false}]'::jsonb),
    ('Node.js', 'EASY', 'What does npm primarily help manage?', 'SINGLE_CHOICE', '[{"text":"JavaScript packages and project scripts","is_correct":true},{"text":"Operating system users","is_correct":false},{"text":"Browser cookies","is_correct":false},{"text":"Database backups only","is_correct":false}]'::jsonb),
    ('Node.js', 'MEDIUM', 'What is the event loop responsible for?', 'SINGLE_CHOICE', '[{"text":"Scheduling callbacks for asynchronous operations","is_correct":true},{"text":"Drawing HTML elements","is_correct":false},{"text":"Compiling SQL schemas","is_correct":false},{"text":"Encrypting source files","is_correct":false}]'::jsonb),
    ('Node.js', 'MEDIUM', 'Which statements about CommonJS modules are correct?', 'MULTIPLE_CHOICE', '[{"text":"require loads a module","is_correct":true},{"text":"module.exports exposes a module value","is_correct":true},{"text":"CommonJS uses import maps only","is_correct":false},{"text":"Every require call starts a new process","is_correct":false}]'::jsonb),
    ('Node.js', 'MEDIUM', 'Why use streams for large files?', 'SINGLE_CHOICE', '[{"text":"They process data in chunks without loading it all at once","is_correct":true},{"text":"They make all operations synchronous","is_correct":false},{"text":"They automatically compress every file","is_correct":false},{"text":"They store data only in the browser","is_correct":false}]'::jsonb),
    ('Node.js', 'MEDIUM', 'What is the Buffer class used for?', 'SINGLE_CHOICE', '[{"text":"Working with binary data","is_correct":true},{"text":"Styling terminal output","is_correct":false},{"text":"Managing browser history","is_correct":false},{"text":"Defining TypeScript interfaces","is_correct":false}]'::jsonb),
    ('Node.js', 'HARD', 'What does backpressure help control in a stream?', 'SINGLE_CHOICE', '[{"text":"A fast producer overwhelming a slower consumer","is_correct":true},{"text":"The order of CSS rules","is_correct":false},{"text":"The number of HTTP headers","is_correct":false},{"text":"The size of a JavaScript function call stack","is_correct":false}]'::jsonb),
    ('Node.js', 'HARD', 'Which statements about the Node.js event loop are correct?', 'MULTIPLE_CHOICE', '[{"text":"A long synchronous callback blocks the event loop","is_correct":true},{"text":"Some filesystem operations use the libuv worker pool","is_correct":true},{"text":"JavaScript callbacks execute simultaneously on many JS threads by default","is_correct":false},{"text":"setTimeout guarantees an exact execution time","is_correct":false}]'::jsonb),
    ('Node.js', 'HARD', 'Why should secrets be read from environment configuration?', 'SINGLE_CHOICE', '[{"text":"To keep deployment-specific secrets out of source code","is_correct":true},{"text":"To make secrets visible to every client browser","is_correct":false},{"text":"To avoid validating configuration","is_correct":false},{"text":"To automatically encrypt the database","is_correct":false}]'::jsonb),

    ('HTML', 'EASY', 'What does the doctype declaration do in an HTML document?', 'SINGLE_CHOICE', '[{"text":"Tells the browser to use standards mode","is_correct":true},{"text":"Loads the page stylesheet","is_correct":false},{"text":"Creates a heading","is_correct":false},{"text":"Declares a JavaScript variable","is_correct":false}]'::jsonb),
    ('HTML', 'EASY', 'What is the purpose of the alt attribute on an image?', 'SINGLE_CHOICE', '[{"text":"Provides a text alternative for the image","is_correct":true},{"text":"Sets the image width","is_correct":false},{"text":"Loads a higher resolution image","is_correct":false},{"text":"Adds a hyperlink automatically","is_correct":false}]'::jsonb),
    ('HTML', 'EASY', 'Which element represents the main content of a page?', 'SINGLE_CHOICE', '[{"text":"main","is_correct":true},{"text":"aside","is_correct":false},{"text":"title","is_correct":false},{"text":"meta","is_correct":false}]'::jsonb),
    ('HTML', 'MEDIUM', 'How should a label be associated with an input?', 'SINGLE_CHOICE', '[{"text":"Set label for to the input id","is_correct":true},{"text":"Set label href to the input class","is_correct":false},{"text":"Place the label inside the input","is_correct":false},{"text":"Set the input alt to the label text","is_correct":false}]'::jsonb),
    ('HTML', 'MEDIUM', 'Which statements about buttons inside forms are correct?', 'MULTIPLE_CHOICE', '[{"text":"A button can use type submit to submit the form","is_correct":true},{"text":"A button can use type button to avoid implicit submission","is_correct":true},{"text":"Every button always submits every form on the page","is_correct":false},{"text":"Button elements cannot contain text","is_correct":false}]'::jsonb),
    ('HTML', 'MEDIUM', 'What is the purpose of the lang attribute on html?', 'SINGLE_CHOICE', '[{"text":"Identifies the primary language of the document","is_correct":true},{"text":"Sets the direction of every CSS animation","is_correct":false},{"text":"Loads translation files automatically","is_correct":false},{"text":"Changes the page URL","is_correct":false}]'::jsonb),
    ('HTML', 'MEDIUM', 'Which element groups related form controls with a caption?', 'SINGLE_CHOICE', '[{"text":"fieldset with legend","is_correct":true},{"text":"section with summary","is_correct":false},{"text":"label with output","is_correct":false},{"text":"form with caption","is_correct":false}]'::jsonb),
    ('HTML', 'HARD', 'Why use semantic HTML elements?', 'SINGLE_CHOICE', '[{"text":"They communicate structure and meaning to browsers and assistive tools","is_correct":true},{"text":"They automatically provide complete CSS styling","is_correct":false},{"text":"They prevent JavaScript from running","is_correct":false},{"text":"They replace HTTP requests","is_correct":false}]'::jsonb),
    ('HTML', 'HARD', 'Which statements about buttons and links are correct?', 'MULTIPLE_CHOICE', '[{"text":"A link navigates to a resource","is_correct":true},{"text":"A button performs an action","is_correct":true},{"text":"A link is always the right control for submitting a form","is_correct":false},{"text":"A button must always have an href","is_correct":false}]'::jsonb),
    ('HTML', 'HARD', 'What does the defer attribute do on a classic external script?', 'SINGLE_CHOICE', '[{"text":"Runs the script after parsing and preserves document order","is_correct":true},{"text":"Runs the script before the HTML document starts","is_correct":false},{"text":"Prevents the script from downloading","is_correct":false},{"text":"Moves the script into a web worker","is_correct":false}]'::jsonb),

    ('CSS', 'EASY', 'What does CSS control?', 'SINGLE_CHOICE', '[{"text":"The presentation and layout of documents","is_correct":true},{"text":"The server database schema","is_correct":false},{"text":"The JavaScript runtime version","is_correct":false},{"text":"The domain name of a website","is_correct":false}]'::jsonb),
    ('CSS', 'EASY', 'What does the universal box-sizing value border-box change?', 'SINGLE_CHOICE', '[{"text":"Width includes content, padding, and border","is_correct":true},{"text":"Margins are included in width","is_correct":false},{"text":"The element becomes a grid container","is_correct":false},{"text":"The element cannot overflow","is_correct":false}]'::jsonb),
    ('CSS', 'EASY', 'Which selector targets an element with class card?', 'SINGLE_CHOICE', '[{"text":".card","is_correct":true},{"text":"#card","is_correct":false},{"text":"card()","is_correct":false},{"text":"@card","is_correct":false}]'::jsonb),
    ('CSS', 'MEDIUM', 'What is CSS specificity used for?', 'SINGLE_CHOICE', '[{"text":"Resolving which competing declaration applies","is_correct":true},{"text":"Choosing the HTML document language","is_correct":false},{"text":"Calculating image resolution","is_correct":false},{"text":"Ordering network requests","is_correct":false}]'::jsonb),
    ('CSS', 'MEDIUM', 'Which statements about Flexbox are correct?', 'MULTIPLE_CHOICE', '[{"text":"It lays out items along a main axis","is_correct":true},{"text":"align-items controls alignment on the cross axis","is_correct":true},{"text":"It requires every child to have position absolute","is_correct":false},{"text":"It only works with text nodes","is_correct":false}]'::jsonb),
    ('CSS', 'MEDIUM', 'What is a CSS media query commonly used for?', 'SINGLE_CHOICE', '[{"text":"Applying styles based on viewport or device conditions","is_correct":true},{"text":"Loading a media file into a database","is_correct":false},{"text":"Changing the HTML language","is_correct":false},{"text":"Declaring a JavaScript module","is_correct":false}]'::jsonb),
    ('CSS', 'MEDIUM', 'What does position relative do?', 'SINGLE_CHOICE', '[{"text":"Keeps the element in normal flow and allows offset positioning","is_correct":true},{"text":"Removes the element from the document","is_correct":false},{"text":"Pins the element to the browser window","is_correct":false},{"text":"Turns the element into a grid container","is_correct":false}]'::jsonb),
    ('CSS', 'HARD', 'Which statements about CSS Grid are correct?', 'MULTIPLE_CHOICE', '[{"text":"It supports row and column tracks","is_correct":true},{"text":"grid-template-columns defines column tracks","is_correct":true},{"text":"It can only place one item","is_correct":false},{"text":"It requires JavaScript to position each cell","is_correct":false}]'::jsonb),
    ('CSS', 'HARD', 'What does inherit do for a CSS property?', 'SINGLE_CHOICE', '[{"text":"Uses the computed value from the parent element","is_correct":true},{"text":"Resets the value to the browser default","is_correct":false},{"text":"Copies the value from the next sibling","is_correct":false},{"text":"Makes the declaration more specific","is_correct":false}]'::jsonb),
    ('CSS', 'HARD', 'What is the main effect of transform translate on an element?', 'SINGLE_CHOICE', '[{"text":"Visually moves it without changing normal document flow","is_correct":true},{"text":"Changes its semantic HTML role","is_correct":false},{"text":"Adds it to the accessibility tree twice","is_correct":false},{"text":"Reorders it in the DOM","is_correct":false}]'::jsonb),

    ('SQL', 'EASY', 'What does SELECT do?', 'SINGLE_CHOICE', '[{"text":"Reads rows from a table or query","is_correct":true},{"text":"Deletes a database server","is_correct":false},{"text":"Creates a CSS class","is_correct":false},{"text":"Starts a network listener","is_correct":false}]'::jsonb),
    ('SQL', 'EASY', 'What does a primary key identify?', 'SINGLE_CHOICE', '[{"text":"A row uniquely within its table","is_correct":true},{"text":"A database password","is_correct":false},{"text":"A server port","is_correct":false},{"text":"A column sort order only","is_correct":false}]'::jsonb),
    ('SQL', 'EASY', 'Which clause filters rows before grouping?', 'SINGLE_CHOICE', '[{"text":"WHERE","is_correct":true},{"text":"HAVING","is_correct":false},{"text":"ORDER BY","is_correct":false},{"text":"VALUES","is_correct":false}]'::jsonb),
    ('SQL', 'MEDIUM', 'What does an INNER JOIN return?', 'SINGLE_CHOICE', '[{"text":"Rows with matching join values in both inputs","is_correct":true},{"text":"Every possible row combination","is_correct":false},{"text":"Only rows with NULL values","is_correct":false},{"text":"Rows from the left input only","is_correct":false}]'::jsonb),
    ('SQL', 'MEDIUM', 'Which statements about foreign keys are correct?', 'MULTIPLE_CHOICE', '[{"text":"They can enforce references between tables","is_correct":true},{"text":"They can prevent deleting a referenced row","is_correct":true},{"text":"They automatically encrypt referenced values","is_correct":false},{"text":"They guarantee every query uses an index","is_correct":false}]'::jsonb),
    ('SQL', 'MEDIUM', 'What does GROUP BY do?', 'SINGLE_CHOICE', '[{"text":"Groups rows so aggregate expressions can be computed per group","is_correct":true},{"text":"Sorts all rows alphabetically by default","is_correct":false},{"text":"Combines two databases into one","is_correct":false},{"text":"Removes every duplicate table","is_correct":false}]'::jsonb),
    ('SQL', 'MEDIUM', 'How is NULL tested in SQL?', 'SINGLE_CHOICE', '[{"text":"IS NULL","is_correct":true},{"text":"= NULL","is_correct":false},{"text":"== empty","is_correct":false},{"text":"IN NULL","is_correct":false}]'::jsonb),
    ('SQL', 'HARD', 'Which statements about database transactions are correct?', 'MULTIPLE_CHOICE', '[{"text":"COMMIT makes transaction changes permanent","is_correct":true},{"text":"ROLLBACK can undo uncommitted changes","is_correct":true},{"text":"A transaction always spans every database server","is_correct":false},{"text":"A SELECT statement cannot run inside a transaction","is_correct":false}]'::jsonb),
    ('SQL', 'HARD', 'What is a common purpose of an index?', 'SINGLE_CHOICE', '[{"text":"Speeding up suitable lookups at the cost of storage and write work","is_correct":true},{"text":"Guaranteeing all queries run in constant time","is_correct":false},{"text":"Replacing the need for constraints","is_correct":false},{"text":"Encrypting table data","is_correct":false}]'::jsonb),
    ('SQL', 'HARD', 'Why use parameterized SQL queries?', 'SINGLE_CHOICE', '[{"text":"To separate query values from SQL syntax and reduce injection risk","is_correct":true},{"text":"To make every query run asynchronously","is_correct":false},{"text":"To disable database permissions","is_correct":false},{"text":"To avoid defining column types","is_correct":false}]'::jsonb),

    ('Git', 'EASY', 'What does git status show?', 'SINGLE_CHOICE', '[{"text":"The current branch and working tree changes","is_correct":true},{"text":"The remote server hardware status","is_correct":false},{"text":"The contents of every remote repository","is_correct":false},{"text":"A list of installed Node.js packages","is_correct":false}]'::jsonb),
    ('Git', 'EASY', 'What is a Git commit?', 'SINGLE_CHOICE', '[{"text":"A recorded snapshot of repository changes","is_correct":true},{"text":"A temporary network connection","is_correct":false},{"text":"A folder that Git ignores","is_correct":false},{"text":"A deleted branch name","is_correct":false}]'::jsonb),
    ('Git', 'EASY', 'What does git branch create?', 'SINGLE_CHOICE', '[{"text":"A movable name for a line of development","is_correct":true},{"text":"A copy of the operating system","is_correct":false},{"text":"A remote database","is_correct":false},{"text":"A package registry","is_correct":false}]'::jsonb),
    ('Git', 'MEDIUM', 'What does git fetch do?', 'SINGLE_CHOICE', '[{"text":"Downloads remote updates without integrating them into the current branch","is_correct":true},{"text":"Deletes all remote branches","is_correct":false},{"text":"Stages every local file","is_correct":false},{"text":"Publishes local commits automatically","is_correct":false}]'::jsonb),
    ('Git', 'MEDIUM', 'Which statements about merge conflicts are correct?', 'MULTIPLE_CHOICE', '[{"text":"They occur when Git cannot automatically reconcile changes","is_correct":true},{"text":"The user may need to edit files and mark them resolved","is_correct":true},{"text":"They always destroy the repository","is_correct":false},{"text":"They can only happen in binary files","is_correct":false}]'::jsonb),
    ('Git', 'MEDIUM', 'What does git stash do?', 'SINGLE_CHOICE', '[{"text":"Temporarily saves uncommitted changes","is_correct":true},{"text":"Permanently deletes the current branch","is_correct":false},{"text":"Uploads all files to a package registry","is_correct":false},{"text":"Rewrites the remote repository history","is_correct":false}]'::jsonb),
    ('Git', 'MEDIUM', 'What is .gitignore used for?', 'SINGLE_CHOICE', '[{"text":"Listing untracked paths Git should normally ignore","is_correct":true},{"text":"Deleting files from every clone","is_correct":false},{"text":"Encrypting repository history","is_correct":false},{"text":"Renaming the default branch","is_correct":false}]'::jsonb),
    ('Git', 'HARD', 'What does git rebase do?', 'SINGLE_CHOICE', '[{"text":"Replays commits onto a different base commit","is_correct":true},{"text":"Combines every branch without changing history","is_correct":false},{"text":"Restores deleted operating system files","is_correct":false},{"text":"Copies Git settings to a new computer","is_correct":false}]'::jsonb),
    ('Git', 'HARD', 'Which statements about reset and revert are correct?', 'MULTIPLE_CHOICE', '[{"text":"Revert creates a commit that undoes earlier changes","is_correct":true},{"text":"Reset can move a branch reference to another commit","is_correct":true},{"text":"Both commands always preserve the same public history","is_correct":false},{"text":"Revert permanently deletes the repository","is_correct":false}]'::jsonb),
    ('Git', 'HARD', 'Why avoid rebasing commits that others have already based work on?', 'SINGLE_CHOICE', '[{"text":"Rebase rewrites commit identities and can disrupt shared history","is_correct":true},{"text":"Rebase removes all file contents","is_correct":false},{"text":"Git forbids pushing any rebased branch","is_correct":false},{"text":"It changes the programming language of the repository","is_correct":false}]'::jsonb)
), inserted_questions AS (
  INSERT INTO questions (skill_id, text, type, difficulty)
  SELECT skill.id, seed.text, seed.question_type, seed.difficulty
  FROM seed
  JOIN skills AS skill ON skill.name = seed.skill_name AND skill.is_active = TRUE
  WHERE jsonb_array_length(seed.options) = 4
    AND EXISTS (
      SELECT 1 FROM jsonb_to_recordset(seed.options) AS option(text TEXT, is_correct BOOLEAN)
      WHERE option.is_correct = TRUE
    )
  RETURNING id, skill_id, text
)
INSERT INTO question_options (question_id, text, is_correct)
SELECT question.id, option.text, option.is_correct
FROM inserted_questions AS question
JOIN seed ON seed.skill_name = (SELECT skill.name FROM skills AS skill WHERE skill.id = question.skill_id)
        AND seed.text = question.text
CROSS JOIN LATERAL jsonb_to_recordset(seed.options) AS option(text TEXT, is_correct BOOLEAN);
